contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function driving the contract and asserting the invariant
    // params:
    //  sendAmt1 - amount of wei to send in first Put call
    //  sendAmt2 - amount of wei to send in second Put call (the decisive call, may be zero)
    //  unlockTime - unlock time argument passed to Put
    function run(uint sendAmt1, uint sendAmt2, uint unlockTime) public payable {
        // ensure this contract has enough balance to forward amounts
        require(address(this).balance >= sendAmt1 + sendAmt2);

        // initial observed balance for this tester in c
        uint before = c.Acc(address(this)).balance;

        // first state-changing call: forward sendAmt1 wei to c.Put
        c.Put{value: sendAmt1}(unlockTime);

        // second state-changing (decisive) call: forward sendAmt2 wei to c.Put
        c.Put{value: sendAmt2}(unlockTime);

        // observed balance after both calls
        uint after = c.Acc(address(this)).balance;

        // The general rule: the final recorded balance increased by exactly sendAmt1+sendAmt2
        // This holds on original P (which allows zero-value Put to still update balance/unlockTime)
        // but is violated by mutant M when sendAmt2 == 0 (M's require(msg.value>0) prevents the second call from changing state)
        assert(after == before + sendAmt1 + sendAmt2);
    }

    // Allow this test contract to receive Ether so it can forward it to c
    receive() external payable {}
}

