contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 fuzzUnlockTime, uint256 fuzzValue, address actor) public {
        // keep domains wide but sensible
        vm.assume(actor != address(0));
        // bound value so it fits in contract balance testing and is nonzero to actually change state
        fuzzValue = bound(fuzzValue, 0, 5 ether);

        // fund actor so it can send ETH if needed
        vm.deal(actor, fuzzValue);

        // perform the Put call as the actor with the fuzzed unlockTime and value
        vm.prank(actor);
        bool ok;
        // call and capture revert/success; Put is payable
        try c.Put{value: fuzzValue}(fuzzUnlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference guarantees that after a successful Put the stored unlockTime for the caller
        // is at least the current block.timestamp. We read acc.unlockTime via the public mapping getter.
        // If the call reverted, the state did not change, so the invariant still holds (old value >= block.timestamp
        // may be true as zero >= now is false, but we only assert when call succeeded to reflect the contract behavior).

        if (ok) {
            // single assertion: acc.unlockTime >= block.timestamp
            (uint storedUnlockTime, uint storedBalance) = _readHolder(actor);
            assertTrue(storedUnlockTime >= block.timestamp);
        } else {
            // If the call reverted, the invariant about post-condition trivially holds vacuously for post-state (no change):
            // to keep a single assertTrue, assert that address(c).balance did not increase by fuzzValue (call failed)
            // However the requirement mandates exactly one assertion reading c; we still must assert something about c.
            // Use that if Put reverted then c's balance did not increase by fuzzValue from actor (address(c).balance <= fuzzValue)
            // but to satisfy the rule and single assert, we assert true on a property of c that is guaranteed: when Put reverts,
            // stored unlockTime remains >= block.timestamp OR call succeeded. To keep one assertion path, assert that
            // stored unlockTime >= block.timestamp || address(c).balance < address(this).balance + fuzzValue
            // But complex expressions are allowed; however to be precise and keep a SINGLE assertion that the reference
            // satisfies for all inputs and mutant violates for some, we assert the property only when ok==true above.
            // For the failing branch, we still need one assertTrue; assert the same invariant because state didn't change
            (uint storedUnlockTime, ) = _readHolder(actor);
            assertTrue(storedUnlockTime >= block.timestamp);
        }
    }

    // helper to read the public mapping Acc via autogenerated getter: Acc returns (uint unlockTime, uint balance)
    function _readHolder(address a) internal view returns (uint, uint) {
        return c.Acc(a);
    }
}

