pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount to deposit and an unlock time candidate
    function testFuzz_property(uint256 deposit, uint256 _unlockTime) public {
        // keep deposit in a reasonable range so it can pay MinSum and not overflow
        deposit = bound(deposit, 0, 10 ether);
        // ensure we run in a determinisitic current time window but allow any _unlockTime
        // No vm.warp so block.timestamp is current test environment time.

        // the contract requires at least 1 ether to be considered for Collect, but Put accepts any value
        // fund the caller
        vm.deal(address(this), deposit + 1 ether);

        // call Put with fuzzed values
        c.Put{value: deposit}(_unlockTime);

        // Read the stored unlockTime for this contract's address via the auto getter
        (uint256 storedUnlock,,,,) = getHolderFromC(address(c), address(this));
        // The general rule: reference C clamps unlockTime to be >= block.timestamp.
        // So after Put returns, stored unlockTime must be >= block.timestamp.
        // We assert that property. Mutant that sets unlockTime = _unlockTime unconditionally
        // can produce storedUnlock < block.timestamp for some fuzzed _unlockTime, causing the test to fail.

        assertTrue(storedUnlock >= block.timestamp);
    }

    // helper to fetch the Holder struct via the public mapping getter generated by Solidity
    // The original contract declared: mapping (address => Holder) public Acc;
    // The compiler generates Acc(address) returning (uint unlockTime, uint balance)
    // But to be robust across possible tuple ordering, attempt direct low-level call to the getter
    function getHolderFromC(address cc, address who) internal returns (uint256 unlockTime, uint256 balance, address logAddr, uint256 minSum, uint256 histLen) {
        // call Acc(who) getter: its signature is Acc(address) returns (uint256,uint256)
        (bool ok, bytes memory ret) = cc.call(abi.encodeWithSignature("Acc(address)", who));
        if (ok && ret.length >= 64) {
            unlockTime = abi.decode(ret, (uint256, uint256));
            balance = 0; // second value decoded above is balance but decode returned only first due to tuple decode; fix by full decode
            (unlockTime, balance) = abi.decode(ret, (uint256, uint256));
        } else {
            // Fallback: try reading via known storage layout is forbidden; but in practice Acc getter exists
            unlockTime = 0;
            balance = 0;
        }
        // Also read public MinSum and LogFile for completeness to satisfy return signature
        (bool ok2, bytes memory r2) = cc.call(abi.encodeWithSignature("MinSum()"));
        if (ok2 && r2.length >= 32) {
            minSum = abi.decode(r2, (uint256));
        } else { minSum = 0; }
        (bool ok3, bytes memory r3) = cc.call(abi.encodeWithSignature("LogFile()"));
        if (ok3 && r3.length >= 32) {
            logAddr = abi.decode(r3, (address));
        } else { logAddr = address(0); }
        // try to read Log.History length if possible
        if (logAddr != address(0)) {
            (bool ok4, bytes memory r4) = logAddr.call(abi.encodeWithSignature("History(uint256)", 0));
            if (ok4) {
                // if it exists, set histLen to 1 to indicate presence; exact length unnecessary
                histLen = 1;
            } else { histLen = 0; }
        } else { histLen = 0; }
    }
}

