        // Now try to collect via attacker: call c.Collect from attacker context
        bool ok;
        try attacker.doCollect(address(c), collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: on the correct contract, if depositor had >= MinSum and amount <= balance and unlock passed,
        // Collect does not revert. We assert that it did not revert (ok == true) OR the depositor had insufficient balance or unlock not passed.
        // Because we want a single assertion that the reference always satisfies and the mutant fails for some input,
        // we express the rule as: if the depositor had sufficient recorded balance and unlockTime passed and collectAmount <= recorded balance,
        // then Collect must not revert. We read c.Acc(attacker) to decide preconditions by calling after the deposit (but before collect) —
        // however Collect was invoked by attacker; to observe the precondition we query the contract state now and use it to form the assertion.

        (uint unlockTime, uint balance) = c.Acc(address(attacker));

        // Precondition in the reference: balance >= MinSum && balance >= collectAmount && block.timestamp > unlockTime
        bool pre = (balance >= c.MinSum()) && (balance >= collectAmount) && (block.timestamp > unlockTime);

        // Single assertion: if pre holds then ok must be true. This is the universal property the reference satisfies for all inputs,
        // and the mutant (using send) will fail for some inputs because attacker fallback consumes >2300 gas causing send to fail and Collect to revert (ok==false).
        assertTrue(!pre || ok);
    }
}

// Adversarial helper whose fallback consumes >2300 gas, causing .send to fail but .call to succeed.
contract AttackerAttacker {
    // deposit by calling C.fallback (which calls Put(0))
    function doDeposit(address cAddr) external payable {
        // forward ETH to c's fallback which calls Put(0)
        (bool s,) = cAddr.call{value: msg.value}("");
        require(s);
    }

    // invoke Collect from this contract
    function doCollect(address cAddr, uint256 am) external {
        C(cAddr).Collect(am);
    }

    // fallback that uses lots of gas
    fallback() external payable {
        // burn gas in a loop
        for (uint i = 0; i < 5000; i++) {
            // do some ops to consume gas
            uint x = i*i;
            x;
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: deposit then attempt Collect which will trigger an external call back to this contract.
    // We make this contract's fallback revert to force the external call to fail.
    receive() external payable { revert(); }

    // single public test function as required
    function runTest(uint putAmount, uint unlockDelay, uint collectAmount) public payable {
        // preconditions to make calls meaningful
        require(putAmount >= c.MinSum(), "put must be at least MinSum");
        // need enough ether to put
        require(msg.value == putAmount, "send exact putAmount as msg.value");
        // compute unlock time in future
        uint unlockTime = block.timestamp + unlockDelay;

        // 1) deposit into c by calling fallback which routes to Put(0) normally; but contract C has fallback calling Put(0)
        // However Put requires an explicit unlock time param; fallback calls Put(0). To call Put with our unlockTime, call Put directly.
        c.Put{value: putAmount}(unlockTime);

        // ensure state is such that Collect's if-condition holds: balance >= MinSum and >= collectAmount and now > unlockTime
        // We need time > unlockTime; simulate by requiring unlockDelay == 0 so unlockTime == block.timestamp
        // But we cannot advance time; instead require unlockDelay == 0 and set unlockTime to block.timestamp in Put invocation above.
        // To keep general, enforce that unlockDelay == 0 so Collect can proceed (block.timestamp > unlockTime is false if equal),
        // so require unlockDelay == type(uint).max will be impossible. Simpler: require(collectAmount <= putAmount && collectAmount > 0 && unlockDelay == 0)
        require(collectAmount <= putAmount, "collectAmount must not exceed deposited amount");
        require(collectAmount > 0, "collectAmount must be > 0");
        require(unlockDelay == 0, "test requires unlockDelay==0 so unlockTime == block.timestamp");

        // 2) Call Collect which will attempt an external call to this contract (which will revert), causing Collect to revert on P but not change balance on M.
        bool success;
        // We call Collect inside a low-level call to capture whether it reverted.
        (success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Observe stored balance via public getter Acc(address).balance — Acc is public so getter exists returning (unlockTime,balance) as a struct; Solidity exposes tuple
        (uint observedUnlock, uint observedBalance) = c.Acc(address(this));

        // On the original contract P, Collect attempts the external transfer after decrementing balance; since our fallback reverts, Collect itself should revert and thus not succeed.
        // Therefore success==false on P. Also because it reverted, the stored balance must remain equal to the original deposited amount.
        // On mutant M, Collect will attempt external call before decrement, so when external call fails it will revert (per code) but the balance would have remained unchanged — however mutant changed ordering so it would decrement only on success; thus observable difference is that on P a failed Collect leaves balance unchanged but also the call fails; on M the logic would allow success==false but balance may differ in other scenarios. The distinguishing rule we assert is:
        // If the external call to Collect returned false (i.e., Collect reverted), then the contract's recorded balance for caller must equal the original deposit minus collectAmount (i.e., balance decreased) — this holds on P (because Collect had already decreased before external call) and is violated by M.

        // However we cannot refer to the original deposit except via putAmount. So assert: if Collect reverted (success==false) then observedBalance == putAmount - collectAmount
        assert(!success ? observedBalance == putAmount - collectAmount : true);
    }
}

